import type { SerializedHyperGraph } from "@tscircuit/hypergraph"
import {
  TinyHyperGraphSolver,
  type TinyHyperGraphProblem,
  type TinyHyperGraphSolverOptions,
  type TinyHyperGraphTopology,
} from "../lib/core"
import {
  loadGraph,
  type LoadGraphError,
  parseGraph,
  type ParseGraphError,
} from "./graph-input"
import { err, ok, type Result } from "./prelude"

/** Expected failure produced while running a lib2 solve. */
export class SolveGraphError extends Error {
  readonly _tag = "SolveGraphError"

  constructor(
    readonly reason: string,
    readonly stats: Record<string, unknown>,
  ) {
    super(`Unable to solve graph: ${reason}`)
  }
}

/** Successful serialized solve output. */
export type SolvedGraph = {
  readonly solver: TinyHyperGraphSolver2
  readonly graph: SerializedHyperGraph
}

/**
 * Lib2 solver facade.
 *
 * This class intentionally reuses the current hot solver engine for the first
 * lib2 slice, so benchmark behavior remains directly comparable while the new
 * boundary API and naming system settle.
 */
export class TinyHyperGraphSolver2 extends TinyHyperGraphSolver {
  constructor(
    topology: TinyHyperGraphTopology,
    problem: TinyHyperGraphProblem,
    options?: TinyHyperGraphSolverOptions,
  ) {
    super(topology, problem, options)
  }

  /**
   * Run the solver and return expected solve failures as values.
   *
   * @returns The current solver on success, or a typed solve error.
   */
  solveResult(): Result<this, SolveGraphError> {
    try {
      this.solve()
    } catch (cause) {
      return err(
        new SolveGraphError(
          cause instanceof Error ? cause.message : String(cause),
          this.stats,
        ),
      )
    }

    if (!this.solved || this.failed) {
      return err(
        new SolveGraphError(this.error ?? "solver did not finish", this.stats),
      )
    }

    return ok(this)
  }
}

/**
 * Create a lib2 solver from loaded topology and problem data.
 *
 * @param topology - Loaded graph topology.
 * @param problem - Loaded routing problem.
 * @param options - Optional solver parameters.
 * @returns A lib2 solver instance.
 */
export function createSolver(
  topology: TinyHyperGraphTopology,
  problem: TinyHyperGraphProblem,
  options?: TinyHyperGraphSolverOptions,
): TinyHyperGraphSolver2 {
  return new TinyHyperGraphSolver2(topology, problem, options)
}

/**
 * Parse, load, solve, and serialize a graph through the lib2 boundary.
 *
 * @param graph - Unknown serialized graph input.
 * @param options - Optional solver parameters.
 * @returns A solved serialized graph or a typed expected failure.
 */
export function solveGraph(
  graph: unknown,
  options?: TinyHyperGraphSolverOptions,
): Result<SolvedGraph, ParseGraphError | LoadGraphError | SolveGraphError> {
  const parsedGraphResult = parseGraph(graph)
  if (parsedGraphResult._tag === "err") {
    return parsedGraphResult
  }

  const loadedGraphResult = loadGraph(parsedGraphResult.value)
  if (loadedGraphResult._tag === "err") {
    return loadedGraphResult
  }

  const solver = createSolver(
    loadedGraphResult.value.topology,
    loadedGraphResult.value.problem,
    options,
  )
  const solveResult = solver.solveResult()
  if (solveResult._tag === "err") {
    return solveResult
  }

  return ok({
    solver,
    graph: solver.getOutput(),
  })
}

/** A typed success or expected-failure result. */
export type Result<T, E extends Error> =
  | { readonly _tag: "ok"; readonly value: T }
  | { readonly _tag: "err"; readonly error: E }

/**
 * Create a successful result.
 *
 * @template T - Success value type.
 * @param value - The successful value.
 * @returns A tagged success result.
 */
export function ok<T>(value: T): Result<T, never> {
  return { _tag: "ok", value }
}

/**
 * Create a failed result.
 *
 * @template E - Expected error type.
 * @param error - The expected error value.
 * @returns A tagged error result.
 */
export function err<E extends Error>(error: E): Result<never, E> {
  return { _tag: "err", error }
}

/**
 * Run a function and classify thrown values as an expected error.
 *
 * @template T - Success value type.
 * @template E - Expected error type.
 * @param run - Work that may throw at a legacy boundary.
 * @param mapError - Converts the thrown value into a typed error.
 * @returns A success result or a typed error result.
 */
export function capture<T, E extends Error>(
  run: () => T,
  mapError: (cause: unknown) => E,
): Result<T, E> {
  try {
    return ok(run())
  } catch (cause) {
    return err(mapError(cause))
  }
}

/**
 * Convert an unknown thrown value to a readable message.
 *
 * @param cause - Unknown thrown value.
 * @returns A message safe to expose in test and benchmark output.
 */
export function getErrorMessage(cause: unknown): string {
  return cause instanceof Error ? cause.message : String(cause)
}

import type { SerializedHyperGraph } from "@tscircuit/hypergraph"
import { loadSerializedHyperGraph } from "../lib/compat/loadSerializedHyperGraph"
import type {
  TinyHyperGraphProblem,
  TinyHyperGraphSolution,
  TinyHyperGraphTopology,
} from "../lib/core"
import { err, ok, type Result } from "./prelude"

/** A serialized graph that has passed lib2 boundary parsing. */
export type ParsedSerializedGraph = SerializedHyperGraph

/** Loaded solver input produced from a parsed serialized graph. */
export type LoadedGraph = {
  readonly topology: TinyHyperGraphTopology
  readonly problem: TinyHyperGraphProblem
  readonly solution: TinyHyperGraphSolution
}

/** Expected failure while parsing serialized graph input. */
export class ParseGraphError extends Error {
  readonly _tag = "ParseGraphError"

  constructor(
    readonly reason: string,
    readonly cause?: unknown,
  ) {
    super(`Invalid serialized graph: ${reason}`)
  }
}

/** Expected failure while loading parsed graph data into solver structures. */
export class LoadGraphError extends Error {
  readonly _tag = "LoadGraphError"

  constructor(readonly cause: unknown) {
    super(
      cause instanceof Error
        ? `Unable to load serialized graph: ${cause.message}`
        : "Unable to load serialized graph",
    )
  }
}

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null

/**
 * Parse unknown input into a serialized hypergraph boundary type.
 *
 * @param graph - Unknown boundary input.
 * @returns A parsed serialized graph or a typed parse error.
 */
export function parseGraph(
  graph: unknown,
): Result<ParsedSerializedGraph, ParseGraphError> {
  if (!isRecord(graph)) {
    return err(new ParseGraphError("expected an object"))
  }

  if (!Array.isArray(graph.regions)) {
    return err(new ParseGraphError("expected regions array"))
  }

  if (!Array.isArray(graph.ports)) {
    return err(new ParseGraphError("expected ports array"))
  }

  if (graph.connections !== undefined && !Array.isArray(graph.connections)) {
    return err(new ParseGraphError("expected connections array when present"))
  }

  // SAFETY: The compat loader owns detailed SerializedHyperGraph semantics.
  // This parser establishes the top-level shape before handing the graph to
  // that boundary adapter.
  return ok(graph as ParsedSerializedGraph)
}

/**
 * Load a parsed serialized graph into topology, problem, and solution values.
 *
 * @param graph - Parsed serialized graph.
 * @returns Loaded graph values or a typed load error.
 */
export function loadGraph(
  graph: ParsedSerializedGraph,
): Result<LoadedGraph, LoadGraphError> {
  try {
    return ok(loadSerializedHyperGraph(graph))
  } catch (cause) {
    return err(new LoadGraphError(cause))
  }
}

