  if (
    currentCandidate.g > runtime.getCandidateBestCost(currentCandidateHopId)
  ) {
    return ROUTE_SEARCH_ADVANCED
  }

  if (runtime.isRegionReservedForDifferentNet(currentCandidate.nextRegionId)) {
    return ROUTE_SEARCH_ADVANCED
